/**
 * @file gymServer.hpp
 * @brief Minimal TCP "gym" bridge between VisibleSim and an external trainer.
 *
 * Generated by utilities/rlAppGenerator. This class is intentionally free of
 * any VisibleSim dependency: it only moves newline-delimited text lines across
 * a TCP socket. All observation/action (de)serialization lives in the block
 * code, which keeps this server reusable across robot families and apps.
 *
 * Threading model:
 *   - start() spawns a background thread that binds/listens/accepts and reads
 *     inbound lines into a thread-safe queue.
 *   - The simulation (scheduler) thread never blocks on socket I/O: it drains
 *     ready action lines with pollLine() and pushes observations with sendLine().
 */

#ifndef GYM_SERVER_HPP_
#define GYM_SERVER_HPP_

#include <atomic>
#include <mutex>
#include <queue>
#include <string>
#include <thread>

class GymServer {
public:
    /// Singleton accessor.
    static GymServer &instance();

    /// Start the server thread listening on `port` (idempotent).
    void start(int port);

    /// Stop the server thread and close all sockets.
    void stop();

    /// @return true once a Python client is connected.
    bool isConnected() const { return connected.load(); }

    /**
     * Pop the next complete inbound line, if any (non-blocking).
     * @param[out] out the line (without trailing '\n')
     * @return true if a line was available
     */
    bool pollLine(std::string &out);

    /**
     * Send one line to the client; a trailing '\n' is appended.
     * @return true on success, false if not connected / write failed
     */
    bool sendLine(const std::string &line);

    ~GymServer();

private:
    GymServer() = default;
    GymServer(const GymServer &) = delete;
    GymServer &operator=(const GymServer &) = delete;

    void serverLoop(int port);   ///< accept + read loop (runs on `worker`)
    void closeClient();

    std::thread worker;
    std::atomic<bool> running{false};
    std::atomic<bool> connected{false};

    int serverFd = -1;
    int clientFd = -1;

    std::mutex inMutex;                 ///< guards inQueue
    std::queue<std::string> inQueue;    ///< complete inbound lines
    std::string rxBuffer;               ///< accumulates partial inbound data

    std::mutex sendMutex;               ///< serializes writes to clientFd
};

#endif /* GYM_SERVER_HPP_ */
